input.command:
powershell -NoProfile -Command "
cd 'c:\Users\KickA\Documents\GitHub\NeuralShell'
\$finalJson = \$null
for (\$i = 0; \$i -lt 50; \$i++) {
  \$raw = gh run view 25832934628 --json status,conclusion 2>&1 | Out-String
  \$jsonLine = ((\$raw -split \"`r?`n\") | Where-Object { \$_ -match '^\s*\{' }) | Select-Object -First 1
  if (-not \$jsonLine) { \$jsonLine = \$raw.Trim() }
  try { \$obj = \$jsonLine | ConvertFrom-Json } catch { Write-Host \"Parse error attempt \$(\$i+1)\"; \$obj = @{ status = 'unknown'; conclusion = '' } }
  Write-Host \"Poll \$(\$i+1)/50: status=\$(\$obj.status) conclusion=\$(\$obj.conclusion)\"
  if (\$obj.status -eq 'completed') { \$finalJson = \$jsonLine.Trim(); break }
  if (\$i -lt 49) { Start-Sleep -Seconds 60 }
}
if (-not \$finalJson) {
  \$raw = gh run view 25832934628 --json status,conclusion 2>&1 | Out-String
  \$finalJson = (((\$raw -split \"`r?`n\") | Where-Object { \$_ -match '^\s*\{' }) | Select-Object -First 1).Trim()
}
Write-Output \"---FINAL_JSON---\"
Write-Output \$finalJson
"
